          "phase": "专注中"
        },
        "noise": {
          "name": "雨声",
          "progress": 62,
          "progressText": "62%"
        },
        "alarmGlyphs": [
          "铃",
          "铃",
          "铃"
        ]
      }
    }
  },
  "assetCandidates": []
}

